        String value = raw.strip();
        if (value.startsWith("jdbc:")) {
            return new JdbcUrl(value, null, null);
        }
        if (!value.startsWith("postgres://") && !value.startsWith("postgresql://")) {
            return new JdbcUrl("jdbc:" + value, null, null);
